// Inlines xterm.js + its fit addon + CSS into a TS module, so the terminal
// WebView works with no internet access and never runs third-party CDN code
// that would see every keystroke. Runs on postinstall; output is gitignored.
const fs = require('fs');
const path = require('path');

const read = (p) => fs.readFileSync(require.resolve(p), 'utf8');
const out = path.join(__dirname, '..', 'src', 'generated', 'xterm.ts');

fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(
  out,
  '// Generated by scripts/inline-xterm.js — do not edit.\n' +
    `export const xtermCss = ${JSON.stringify(read('@xterm/xterm/css/xterm.css'))};\n` +
    `export const xtermJs = ${JSON.stringify(read('@xterm/xterm/lib/xterm.js'))};\n` +
    `export const fitAddonJs = ${JSON.stringify(read('@xterm/addon-fit/lib/addon-fit.js'))};\n`
);
